export const TimePeriodType = {
  YTD: 'YTD',
  HALF: 'HALF',
  QTR: 'QTR',
  R3M: 'R3M',
  MTH: 'MTH',
  FY: 'FY',
} as const;

export type TimePeriodType =
  (typeof TimePeriodType)[keyof typeof TimePeriodType];

/** Selector behavior whitelist. Labels and ordering come from the preset. */
const SUPPORTED_TIME_PERIOD_TYPES = new Set<string>(
  Object.values(TimePeriodType),
);

export const isTimePeriodType = (value: unknown): value is TimePeriodType =>
  typeof value === 'string' && SUPPORTED_TIME_PERIOD_TYPES.has(value);
